from collections import defaultdict

def next_permutation(p):
    # Find the longest increasing subsequence from the end
    for i in range(len(p) - 2, -1, -1):
        if p[i] < p[i + 1]:
            j = i + 1
            while j < len(p) and p[j] < p[i]:
                j += 1
            right = p[j:]
            left = p[:i + 1]
            right = sorted(right)
            return left + right[::-1]
    return p[::-1]

def period_length(a):
    if a[1] - a[0] > 0 and a[-2] - a[-1] > 0:
        return len(a)
    p = a
    while p != next_permutation(p):
        if p == a:
            break
        p = next_permutation(p)
    return 1 + period_length(p)

