        self.box_positions.sort()
        self.box_positions.append(len(self.box_positions) * len(self.box_positions))

    def getIntervalEnergy(self, interval_start, interval_end):
        interval_positions = [0, interval_start - 1, interval_end - 1, len(self.box_positions) - 1]
        interval_sum = sum(self.box_positions[i] for i in interval_positions)
        total_energy = interval_sum * sum(self.weights[i] for i in interval_positions)
        for change in self.value_changes:
            if i < start:
                total_energy += interval_sum - self.box_positions[interval_start - 1]
            if i > end:
                total_energy -= self.box_positions[interval_end - 1]
            interval_sum -= self.weights[i] if not start else self.weights[i] - self.weights[change]
        return total_energy % mod

    def moveBoxes(self, start, end, boxes_changes):
        old_start, old_end = start, end
        for change in boxes_changes:
            if old_start != start:
                self.box_positions[start] -= self.weights[self.box_positions.index(start)]
                old_start = start
            if old_end != end:
                self.box_positions[end] -= self.weights[self.box_positions.index(end)]
                old_end = end
            self.weights[change] -= self.weights[self.weights.index(start)]

    def updateBoxWeights(self, weights_changes):
        for change in weights_changes:
            start, end = self.weights.index(change), self.weights.index(change)
            self.value_changes.append((start, end))

    def optimizeInterval(self, interval_start, interval_end, result):
        self.moveBoxes(interval_start, interval_end, self.value_changes)
        result[0] = self.getIntervalEnergy(interval_start, interval_end)

        if interval_start > 0:
            self.moveBoxes(interval_start - 1, interval_end, result)
            result[1] = self.getIntervalEnergy(interval_start - 1, interval_end)

        if interval_start > 0 and interval_end < len(self.box_positions):
            self.moveBoxes(interval_start, interval_end + 1, result)
            result[2] = self.getIntervalEnergy(interval_start, interval_end + 1)

        if interval_start:
            self.moveBoxes(interval_start, interval_end, result)
            result[3] = self.getIntervalEnergy(interval_start, interval_end)

    def solveQueries(self, queries):
        result = [0] * len(queries)
        for i, query in enumerate(queries):
            if query[0] > 0:
                end = query[0]
                for start in range(query[0], query[1] + 1):
                    self.updateBoxWeights(start)
                    self.optimizeInterval(start - 1, end, result)
            else:
                start = query[1]
                end = query[0]
                if start:
                    self.optimizeInterval(start, end, result)
        return result

