from math import factorial

# Function to calculate modular inverse using Extended Euclidean Algorithm
def modinv(a, m):
    g, x, y = extended_euclidean(a, m)
    if g != 1: 
        raise ValueError('Multiplicative inverse does not exist')
    return x % m

# Function to perform Extended Euclidean Algorithm
def extended_euclidean(a, b):
    if a == 0:
        return (b, 0, 1)
    else:
        g, y, x = extended_euclidean(b % a, a)
        return (g, x - (b // a) * y, y)

# Function to calculate numerator in the expected time formula
def numerator(n, a):
    numerator = 0
    for i in range(1, n + 1):
        factorial_i = 1
        for j in range(1, i + 1):
            factorial_i *= j
        factorial_i -= factorial(i - 1)
        numerator += factorial_i * pow(i, a, n) * pow(factorial(i), -1, n)
    return numerator

# Function to calculate denominator in the expected time formula
def denominator(n, a):
    denominator = 1
    for i in range(1, n + 1):
        factorial_i = 1
        for j in range(1, i + 1):
            factorial_i *= j
        factorial_i -= factorial(i - 1)
        denominator *= factorial_i
    return denominator

# Calculate the expected time
def expected_time(n, a):
    numerator_value = numerator(n, a)
    denominator_value = denominator(n, n)
    numerator_value = numerator_value % (10**9 + 7)
    denominator_value = denominator_value % (10**9 + 7)
    Q = modinv(denominator_value, (10**9 + 7))
    return (numerator_value * Q) % (10**9 + 7)

