from collections import deque

def cook_cutlet(n, k, flip_periods):
    prev_roasts = [False] * n
    final_flip_count = 0

    for fr in flip_periods:
        left_end, right_end = fr
        if left_end != right_end:
            left_end += 1
            right_end += 1
        next_to_left_idx = right_end
        next_to_right_idx = max(left_end - 1, 0)
        cur_interval_idx = 0
        for p in range(n):
            if prev_roasts[p] == False:  # In between
                if p < cur_interval_idx:
                    prev_roasts[p] = True
                elif p < next_to_left_idx:
                    prev_roasts[p] = False
                elif p < next_to_right_idx:
                    prev_roasts[p] = False
                else:
                    final_flip_count += 1
                    prev_roasts[p] = True
                    if next_to_left_idx == next_to_right_idx-1:
                        next_to_right_idx += 1
                    cur_interval_idx += 1

            elif p == cur_interval_idx and not prev_roasts[p]:
                prev_roasts[p] = True
                final_flip_count += 1
                cur_interval_idx += 1
            elif p > cur_interval_idx:
                if p - 1 >= next_to_right_idx:
                    final_flip_count += 1
                    prev_roasts[p] = True
                    next_to_right_idx += 1
                    if next_to_right_idx == next_to_left_idx+1:
                        next_to_left_idx += 1
                    cur_interval_idx += 1
                else:
                    prev_roasts[p] = False

            if next_to_right_idx + 1 == n:
                break

    for p in range(len(prev_roasts)):
        if prev_roasts[p]:
            final_flip_count += 1

    if final_flip_count == k:
        return 'Full'
    else:
        return 'Hungry'

