def game_winner_pattern(N, M, K, MOD=10**9+7):
    if N + M + K == 2:
        if N == 1 and (M + K == 1 or M == 0 and K == 1):
            return 1
        elif M == 1 and (N + K == 1 or N == 0 and K == 1):
            return 1
        elif N == 2:
            return 1
        elif M == 2:
            return 1
        elif K == 2:
            return 1
        else:
            return 2
    # Calculate the total number of derangements (cards will end up in the wrong position)
    total_patterns = pow(6, M+N+K, MOD) - pow(3, M, MOD) - pow(3, N, MOD)

    # Calculate the number of winners for each starting card
    alice_wins = sum([3**(-1*M-1)*(9*M*3**M-M**2*8%MOD) for M in range(N)])
    bobby_wins = sum([3**(-1*M-1)*(9*N*3**N-N**2*8%MOD) for N in range(M)])
    charlie_wins = sum([3**(-1*M-1)*(9*K*3**K-K**2*8%MOD) for K in range(K)])

    # Total number of winners
    ans = pow(3, N, MOD) + pow(3, M, MOD) + pow(3, K, MOD) - alice_wins - bobby_wins - charlie_wins
    if ans < 0:
        return 0
    return int(ans % MOD)

