def find_path(edges, degree):
    # Initialize the graph based on the tree structure and degrees of vertices
    graph = defaultdict(list)
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    path_queue = deque([])
    in_degree = {vertex: 0 for vertex in range(1, n + 1)}

    # Calculate in degrees for all vertices
    for i, d in enumerate(degree):
        if d == -1:
            continue
        for vertex in range(1, d + 1):
            in_degree[vertex] += 1

    # Build a starting path
    path_queue.extend([vertex for vertex in range(1, n + 1) if in_degree[vertex] == 0])
    output_degree = {}
    while len(path_queue) > 0:
        vertex = path_queue.popleft()
        for next_vertex in graph[vertex]:
            output_degree[next_vertex] = in_degree[next_vertex]
            degree[next_vertex].append(-output_degree[next_vertex])
            in_degree[next_vertex] = 0
            if in_degree[next_vertex] == 0:
                path_queue.append(next_vertex)

    if min(degree) >= -2:  # Check if any path can lead to a win
        output_degree = collections.defaultdict(list)
        for vertex, d in output_degree.items():
            output_degree[vertex] = d + degree[vertex] + 1
            for next_vertex in graph[vertex]:
                if d < -output_degree[next_vertex]:
                    output_degree[next_vertex] += d
                    degree[vertex].append(-output_degree[next_vertex])

        path_queue.extend([vertex for vertex in range(1, n + 1) if output_degree[vertex] >= 0])
        while len(path_queue) > 0:
            vertex = path_queue.popleft()
            for next_vertex in graph[vertex]:
                if output_degree[next_vertex] == -1:
                    output_degree[next_vertex] += output_degree[vertex] + 1
                    degree[vertex].append(-output_degree[next_vertex])
                if output_degree[next_vertex] < 0:
                    i = 0 if output_degree[next_vertex] < -2 else output_degree[next_vertex] - 2
                    output_degree[next_vertex] += i
                    degree[vertex].append(-output_degree[next_vertex])

        if -min(degree) == min(degree):
            return "Black"
        else:
            return "White"
    else:
        return "Draw"

