def min_cost_to_reach_multi_set(multiset, lengths):
    original_costs = [sum(lengths[i]) for i in range(len(multiset))]
    frequencies = [defaultdict(int) for _ in range(len(multiset))]

    for i, multiset_sym in enumerate(multiset):
        for j in range(len(multiset_sym)):
            frequencies[i][multiset_sym[j]] += 1

    total_costs = []
    for freq in frequencies:
