            if start <= time <= end or key in flips_with_index and time >= key:
                prev_key = key
        if prev_key is None and time <= n:
            return -1  # Unable to fry cutlet for the needed time
        if prev_key is not None:
            previous = stacks.get(prev_key, [])(0)
            final = stacks.get(key, [])(time - previous.n)
            if min_cost is None or final < min_cost:
                min_cost = final
                min_key = key

