from collections import defaultdict

def get_loops(graph):
    paths = defaultdict(list)
    for u, v in graph.edges:
        paths[u].append((u, v))
        paths[v].append((v, u))
    return paths

def dfs(node, parent, color, graph, loops, paths):
    if node not in graph or not paths[node]:
        return
    if len(paths[node]) > 3:
        return
    for path in paths[node]:
        next_node = path[1]
        if not loops[next_node] and not dfs(next_node, node, color, graph, loops, paths):
            return False
    loops[node] = True
    for path in paths[node]:
        if path[1] == parent:
            continue
        if dfs(path[1], node, color, graph, loops, paths):
            return True
    return False

def tic_tac_toe(game_state, graph):
    loops = get_loops(graph)
    players = {'N': {'W': {}, 'B': {}}}
    for player, color in [('B', 'N'), ('W', 'W')]:
