def binary_search(arr, low, high, target):
    """Perform binary search to find the target in the subarray [low, high]"""
    while low < high:
        mid = (low + high) // 2
        if arr[mid] < target:
            low = mid + 1
        else:
            high = mid
    return low

class LineSegment:
    """Class to represent a range of cells on an infinite line"""
    def __init__(self, cells):
        self.start = cells[0]
        self.end = cells[-1]
        self.totalDistance = 0

    def add_weight(self, cell, weight):
        """Add weight from cell to the segment"""
        if cell < self.start:
            start = cell
        elif cell > self.end:
            end = cell
        else:
            start = self.start
            end = self.end

        self.totalDistance += weight
        self.start = start
        self.end = end

