from typing import List
import heapq

def min_spanning_tree(n: int, k: int, degrees: List[int], edges: List[List[int]]) -> int:
    # Create a dictionary to store the weights of edges for vertices <= k
    weights_k = {}
    for i in range(k):
        for j in range(i + 1, i + degrees[i] + 1, 1):
            weights_k[(i, j - 1)] = edges[i][j - 1]

    # Priority queue to store the weights of edges that need to be considered
    queue = []
    for i in range(k):
        for j in range(i + 1, min(i + 1 + degrees[i], k + 1)):
            heapq.heappush(queue, (edges[i][j - 1], i, j - 1))

    # Minimum spanning tree algorithm
    total_weight = 0
    while queue:
        weight, i, j = heapq.heappop(queue)
        if (i, j) in weights_k:
            total_weight += weight
            del weights_k[(i, j)]
        else:
            # If an edge has no weights, we need to consider it separately
            if (j, i) not in weights_k:
                weights_k[(j, i)] = edges[j][i]
                for k in range(j, min(j + 1 + degrees[j], k + 1)):
                    heapq.heappush(queue, (edges[k][i], k, i))
            else:
                total_weight += weights_k[(j, i)]
                del weights_k[(j, i)]

    return total_weight

